from selenium.webdriver.common.by import By
from taf.selenium.nms.nom.pages.LoginPage import LoginPage
import time


class Menu(LoginPage):
    """
    The class manages which menu tab will be clicked
    """
    FIRST_MENU_INDEX = 0
    _MAIN_MENU_XPATH = "//*[@id='{}']"
    _ACTIVE_PAGE_XPATH = "//div[@data-key='{}' and contains(@style, 'position: fixed')]"

    def open_page(self, menu_list):
        """
        Open a new page of selenium_nom web, if target page has been opened, it won't be opened again
        :param menu_list: the menu list of selenium_nom's page
        """

        menu_xpath_list = list()
        menu_xpath_list.append(self._MAIN_MENU_XPATH.format(menu_list[self.FIRST_MENU_INDEX]))

        if self._is_page_active(menu_list):
            return

        for index, xpath in enumerate(menu_xpath_list):
            self.click_enabled_element((By.XPATH, xpath))
        time.sleep(10)

    def _is_page_active(self, menu_list):
        xpath = self._ACTIVE_PAGE_XPATH.format(menu_list[self.FIRST_MENU_INDEX])
        if self.element_exists((By.XPATH, xpath), timeout=10):
            return True
        else:
            return False
